"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "checkout",
    "uid": "uid-deployment-checkout"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "640Mi"
        }
      }
    }
  },
  "expected_effect": "The increased memory limit should prevent OOM kills by allowing the container to use more memory before being terminated.",
  "rationale": "The container's memory usage peaked at 100% of its 512Mi limit, leading to OOM kills. Increasing the limit to 640Mi (25% higher) provides a buffer for increased memory demand without requiring a rollback.",
